function fib(n, memo = new Map()) {
  if (n <= 1)
    return n;

  if (memo.has(n)) 
    return memo.get(n); // use already calculated value

  const value = fib(n - 1, memo) + fib(n - 2, memo);

  memo.set(n, value); // store value just calculated

  return value;
}

