long long fib(int n, std::unordered_map<int, long long>& memo) {
    if (n <= 1) return n;
    auto found = memo.find(n);
    if (found != memo.end()) return found->second;   // already answered
    long long value = fib(n - 1, memo) + fib(n - 2, memo);
    memo[n] = value;                                 // write it down
    return value;
}

